/** The statements taken for people on a sheet. Taking one records the person's due-total and binds
 *  each claim of theirs that counts to the figure it shows then; the rest are left unbound. */
@Service
public class StatementService {

    /** Written for a due-total that has no rate to work from. */
    private static final String NO_RATE = "n/a";

    private final StatementRepository statements;
    private final ClaimRepository claims;
    private final ClaimService claimService;
    private final PersonRepository people;
    private final RateService rates;
    private final PersonGradeService grades;
    private final PersonService personService;
    private final SheetService sheets;
    private final SettingService settings;
    private final Audit audit;

    public StatementService(StatementRepository statements, ClaimRepository claims, ClaimService claimService,
            PersonRepository people, RateService rates, PersonGradeService grades, PersonService personService,
            SheetService sheets, SettingService settings, Audit audit) {
        this.statements = statements;
        this.claims = claims;
        this.claimService = claimService;
        this.people = people;
        this.rates = rates;
        this.grades = grades;
        this.personService = personService;
        this.sheets = sheets;
        this.settings = settings;
        this.audit = audit;
    }

    /** Each person's statement summary on the sheet, by person id; a person with none is absent. */
    public Map<Long, StatementSummary> summaries(String sheetId) {
        return statements.findBySheetIdOrderByIdAsc(sheetId).stream()
                .collect(Collectors.groupingBy(Statement::getPersonId,
                        Collectors.collectingAndThen(Collectors.toList(), StatementSummary::of)));
    }

    public StatementSummary summary(String sheetId, Long personId) {
        return StatementSummary.of(statements.findBySheetIdAndPersonIdOrderByIdAsc(sheetId, personId));
    }

    /** Take a statement for a person: their claims, newest first, as bound by it. */
    @Transactional
    public List<Claim> take(String sheetId, String user, Long personId) {
        // Lock the sheet, so a claim changed or a statement taken at the same moment waits.
        sheets.lock(sheetId);
        Person person = people.findByIdAndSheetId(personId, sheetId)
                .orElseThrow(() -> new NoSuchElementException("No person " + personId + " on sheet " + sheetId));
        LocalDate today = sheets.today(sheetId);
        List<Claim> theirs = claims.findBySheetIdAndPersonIdOrderByListedDesc(sheetId, personId);
        List<PersonHold> holds = personService.holds(personId);
        BigDecimal total = BigDecimal.ZERO.setScale(2);
        boolean anyFigure = false;
        int counted = 0;
        for (Claim claim : theirs) {
            // A held or deferred claim is left out of the statement, whether or not an earlier one bound it.
            if (!claim.counts() || claim.heldBy(holds) || claim.deferredOn(today)) {
                claim.unbind();
                continue;
            }
            // The statement binds the figure; the late charge on top keeps following the sheet's today.
            BigDecimal figure = claimService.figureOf(sheetId, person, claim);
            if (figure != null) {
                total = total.add(claimService.dueOf(sheetId, person, claim));
                anyFigure = true;
            }
            claim.bind(figure);
            counted++;
        }
        claims.saveAllAndFlush(theirs);
        boolean hasRate = rates.rateOn(sheetId, grades.gradeOn(person.getId(), today), today).isPresent();
        String dueTotal = hasRate || anyFigure ? settings.capped(sheetId, total).toPlainString() : NO_RATE;
        statements.saveAndFlush(new Statement(sheetId, personId, today, dueTotal, counted));
        audit.recordOnCommit("STATEMENT sheet=" + sheetId + " by=" + user + " name=" + person.getName()
                + " due-total=" + dueTotal + " claims=" + counted);
        return theirs;
    }
}
package net.officefloor.hq.app.statement;

import java.time.LocalDate;
import java.util.List;

/** A person's statements as their row shows them: how many were taken, and the last one's
 *  due-total and date (null when none was taken). */
public record StatementSummary(int count, String lastDueTotal, LocalDate lastDate) {

    public static final StatementSummary NONE = new StatementSummary(0, null, null);

    /** The summary of one person's statements, in the order they were taken. */
    public static StatementSummary of(List<Statement> statements) {
        if (statements.isEmpty()) {
            return NONE;
        }
        Statement last = statements.get(statements.size() - 1);
        return new StatementSummary(statements.size(), last.getDueTotal(), last.getTakenOn());
    }
}
-- A statement taken for a person: the sheet's today when it was taken, the person's due-total then
-- ("n/a" when their grade had no rate and no claim of theirs kept a figure) and how many of their
-- claims counted. A person's last statement is the one with the highest id.
CREATE TABLE statement (
    id BIGINT AUTO_INCREMENT PRIMARY KEY,
    sheet_id VARCHAR(200) NOT NULL REFERENCES sheet (id),
    person_id BIGINT NOT NULL REFERENCES person (id),
    taken_on DATE NOT NULL,
    due_total VARCHAR(20) NOT NULL,
    claims INT NOT NULL
);
CREATE INDEX statement_person ON statement (person_id, id);
CREATE INDEX statement_sheet ON statement (sheet_id, id);

-- A claim bound by its person's last statement shows and totals the figure it had then (null when
-- it had none) until the next statement rebinds or unbinds it.
ALTER TABLE claim ADD COLUMN stated BOOLEAN NOT NULL DEFAULT FALSE;
ALTER TABLE claim ADD COLUMN stated_due DECIMAL(12, 2);

